INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12281, 74944, 'tt1861375', NULL, 'War of the Buttons', 'La Guerre des boutons', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/aIrflAHfv1BTnrS8k1QSoCUKVEK.jpg', 'https://image.tmdb.org/t/p/original/5li8dEJE67Ahe5j3gZPEY0ZRsgm.jpg', 'A village in the South of France, 1960. A band of country boys aged 7 to 14, led by fearless young Lebrac, wages an uncompromising battle against their sworn rivals, the kids from the neighboring village. A war of honor and allegiance that''s been kept alive for generations, in which humiliation is the most fearsome defeat and no tactic is too extreme, including attacking the enemy stark naked!', NULL, NULL, 1.7612, 6.048, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12282, 55033, 'tt0103900', NULL, 'The Buttercream Gang', 'The Buttercream Gang', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/cOwKydnK3lWxCpS3bvdsXW08clO.jpg', 'https://image.tmdb.org/t/p/original/tdjg01UeZ8BFYA9ppgW4KQQTSXy.jpg', 'Unlike most gangs, the ButterCream gang does good deeds. Their leader, Pete, has to go live with his aunt in Chicago. But things don''t go well in Chicago and Pete is changed when he returns. Soon Pete is hanging around with the wrong crowd. But the remaining members of the gang, especially their new leader Scott, refuse to give up on their friend Pete.', NULL, NULL, 0.9054, 6.028, 0, 1.02, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12283, 7009, 'tt0466195', NULL, 'The Wild Chicks', 'Die Wilden Hühner', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/vAC70LZDVyOhHGV35hckNgIaLIi.jpg', 'https://image.tmdb.org/t/p/original/al2wuRIRxEIYJ1izF1MKKXfnERQ.jpg', 'Twelve-year-old Sprotte has a ''gang'' with her three friends Frieda, Melanie, and Trude. Together, the girls care for Sprotte''s grandmother''s chickens. The new girl in school, Wilma, wishes to join the group, which Melanie is very unhappy about, and on top of all of that they have an ongoing revalisasion with a group of boys.', NULL, NULL, 1.4691, 6.215, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12284, 14685, 'tt0072233', NULL, 'Swallows and Amazons', 'Swallows and Amazons', 'movie', 1974, 'https://image.tmdb.org/t/p/w500/lewCN0u5NOE7fBSPLP2NqGFrKeK.jpg', 'https://image.tmdb.org/t/p/original/ck3BUeBWD7qwICULWlVVHx2kIdM.jpg', 'On holiday with their mother in the Lake District in 1929 four children are allowed to sail over to the nearby island in their boat Swallow and set up camp for a few days. They soon realise this has been the territory of two other girls who sail the Amazon, and the scene is set for serious rivalry.', NULL, NULL, 1.2837, 7.548, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12285, 64265, 'tt0117287', NULL, 'The Paper Brigade', 'The Paper Brigade', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/qV8wZhGUAm6WJ0V5XeIJgScAIYW.jpg', 'https://image.tmdb.org/t/p/original/9M6NsVPnxVtlY5JqSJ1TL2ev3QI.jpg', 'A 14 year old boy named Gunther moves to a small town with his parents and little brother. He meets up with a group of overly charitable paper boys who want him to sub for their friend while he''s out of town. Gunther agrees so he can get enough money for concert tickets to take his blonde and beautiful crush too, all the while dealing with Chad, her wannabe boyfriend and his bully friends. All in all, Gunther learns to respect himself and other people and to have fun during it all.', NULL, NULL, 1.116, 6.907, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
