INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12294, 530079, 'tt9193612', NULL, 'Ride Your Wave', 'きみと、波にのれたら', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/byoY2stdullEcVjlaWs1ENXyrDm.jpg', 'https://image.tmdb.org/t/p/original/vooRKLGVvFRFmx9swcMh26uYZSf.jpg', 'Hinako is a surf-loving college student who has just moved to a small seaside town. When a sudden fire breaks out at her apartment building, she is rescued by Minato, a handsome firefighter, and the two soon fall in love.', NULL, NULL, 3.3105, 7.5, 0, 9.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12295, 186969, 'tt2450486', NULL, 'Rainbow Fireflies', '虹色ほたる 〜永遠の夏休み〜', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/hNiOMm90Ei3prxgh3nnbXv9WVKG.jpg', 'https://image.tmdb.org/t/p/original/qnWmb4S1DHbh4CrJMORiZZKCzL5.jpg', 'One year ago, Yūta lost his father in a car crash. Now in the 6th grade, Yūta goes to catch beetles in a dam near a mountain, a place he often went with his father. There, Yūta meets a strange old man, and while walking in heavy rainfall, slips and blacks out. When Yūta awakes, he sees a child, Saeko, who shows him a village from the past. A precious summer vacation for Yūta begins.', NULL, NULL, 1.4762, 7.1, 0, 8.53, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12296, 66788, 'tt0083021', NULL, 'Sailor Suit and Machine Gun', 'セーラー服と機関銃', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/6gSmxfFhzVXr1hGXfda0K86rIIA.jpg', 'https://image.tmdb.org/t/p/original/hB6yUlvrQ2MQ0ySxviBgFaK2CDG.jpg', 'A high-school girl inherits a declining yakuza organization, which seeks to repair its fortunes under her leadership.', NULL, NULL, 1.9339, 7.041, 0, 7.51, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12297, 798544, 'tt15052770', NULL, 'Summer Ghost', 'サマーゴースト', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/mMXaAvvSw24hYNchhCtCM5z6fhB.jpg', 'https://image.tmdb.org/t/p/original/xXliNn9WUSqv5MkjrwD3cp1xXNr.jpg', 'An urban legend says that lighting fireworks at an abandoned airfield will beckon the "summer ghost," a spirit that can answer any question. Three teenagers, Tomoya, Aoi, and Ryo, each have their own reason to show up one day. When a ghost named Ayane appears, she reveals she is only visible to those "who are about to touch their death." Compelled by the ghost and her message, Tomoya begins regularly visiting the airfield to uncover the true purpose of her visits.', NULL, NULL, 3.2173, 7.299, 0, 8.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12298, 513347, 'tt8176578', NULL, 'Flavors of Youth', '肆式青春', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/ueHeH5ergeHx27L4SCI9qlmwczA.jpg', 'https://image.tmdb.org/t/p/original/iRB6VKJuFd88bk20hvLqlDzi4kP.jpg', 'The rigorous city life of China, while bustling and unforgiving, contains the everlasting memories of days past. Three stories told in three different cities, follow the loss of youth and the daunting realization of adulthood. Though reality may seem ever changing, unchangeable are the short-lived moments of one''s childhood days. A plentiful bowl of noodles, the beauty of family and the trials of first love endure the inevitable flow of time, as three different characters explore the strength of bonds and the warmth of cherished memories. Within the disorder of the present world, witness these quaint stories recognize the comfort of the past, and attempt to revive the neglected flavors of youth.', NULL, NULL, 3.3196, 6.876, 0, 8.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12299, 345731, 'tt4119590', NULL, 'Initiation Love', 'イニシエーション・ラブ', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/kfWtj2VC3D4MZHrY2p7p2DzCDzm.jpg', 'https://image.tmdb.org/t/p/original/xVThZqhO8xySycTKXd2TJCmssvO.jpg', 'Set in Shizuoka and Tokyo, Japan in the late 1980''s. Takkun is a university student in Shizuoka attempting to find a job. Mayu is a dental hygienist. They meet through a blind date and begin to date, but Takkun finds a job in Tokyo and goes there. They begin a long distance relationship, but their relationship breaks down.', NULL, NULL, 1.3718, 7.4, 0, 7.51, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12300, 667, 'tt0062512', NULL, 'You Only Live Twice', 'You Only Live Twice', 'movie', 1967, 'https://image.tmdb.org/t/p/w500/gIhS0VC7YzI8pj6zfS3KxsxV0dS.jpg', 'https://image.tmdb.org/t/p/original/cpZAXIYA0lkZMpAt7d1MmH8ojNV.jpg', 'A mysterious spacecraft captures Russian and American space capsules and brings the two superpowers to the brink of war. James Bond investigates the case in Japan and comes face to face with his archenemy Blofeld.', NULL, NULL, 11.2264, 6.586, 0, 7.51, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12301, 334030, 'tt4192636', NULL, 'Forget Me Not', '忘れないと誓ったぼくがいた', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/s80LGHpj1hNlLW9WMjAROhdL6Lu.jpg', 'https://image.tmdb.org/t/p/original/dVHziH3Q2X88UvLpEJ7HfSwITev.jpg', 'Takashi Hayama is a third year high school student. He falls in love with Azusa Oribe at first sight and they begin to date.  One day, Azusa tells Takashi "people who meet me, forget about me several hours later."  Takashi doesn''t believe Azusa, but by chance he realizes that he forgot about Azusa. So he won''t forget Azusa, Takashi begins to leave a note for himself and Azusa.', NULL, NULL, 1.8735, 6.4, 0, 6.51, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
