INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12304, NULL, NULL, 1343, 'The World Ends with You', 'The World Ends with You', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1n67.jpg', NULL, 'In the game, Neku Sakuraba and his allies are forced to participate in a game that will determine their fate. The battle system uses many of the unique features of the Nintendo DS, including combat that takes place on both screens, and attacks performed by certain motions on the touchscreen or by shouting into the microphone. Elements of Japanese youth culture, such as fashion, food, and cell phones, are key aspects of the missions.', 'https://www.igdb.com/games/the-world-ends-with-you', '["Nintendo DS"]', NULL, NULL, 0, 10.54, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
