INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12320, 4543, 'tt0085959', NULL, 'Monty Python''s The Meaning of Life', 'Monty Python''s The Meaning of Life', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/9yavZ9WgEZIpWi2EbVW8At9RPdo.jpg', 'https://image.tmdb.org/t/p/original/eIcJq4QDmToJeu4g6fS4iLPKY8n.jpg', 'Life''s questions are ''answered'' in a series of outrageous vignettes, beginning with a staid London insurance company which transforms before our eyes into a pirate ship. Then there''s the National Health doctors who try to claim a healthy liver from a still-living donor. The world''s most voracious glutton brings the art of vomiting to new heights before his spectacular demise.', NULL, NULL, 5.7894, 7.308, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
