INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12325, 31273, 'tt0128378', NULL, 'With Fire and Sword', 'Ogniem i mieczem', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/qyBPfr9ue5EhdaVne14XA3Zxacs.jpg', 'https://image.tmdb.org/t/p/original/7GPLVxu5FcGVmyC1kBht8Nd8DUA.jpg', 'In the mid-17th century, Poland was the largest, most democratic, and most tolerant country in Europe. However, a tragic civil war brought about the gradual decline of the once glorious republic...  An epic story about the Cossack rebellion against the Polish-Lithuanian Commonwealth.', NULL, NULL, 2.0789, 6.883, 0, 4.015, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12326, 176088, 'tt1038693', NULL, 'The Story of Luke', 'The Story of Luke', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/dSXad96zPtphKHnDNiOD34EhcA0.jpg', 'https://image.tmdb.org/t/p/original/2OnV8ULU0GVsRvXX0BvpUiD5wdc.jpg', 'Sheltered by his grandparents, Luke, a young man with autism, is thrust into a world that doesn''t expect anything from him. But Luke is on a quest for a job and true love. And he isn''t taking no for an answer.', NULL, NULL, 1.5949, 6.9, 0, 7.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12327, 86290, 'tt2100380', NULL, 'A Smile as Big as the Moon', 'A Smile as Big as the Moon', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/unCNX0qBYEW6KXBxOdRh8Z93B1y.jpg', 'https://image.tmdb.org/t/p/original/xAG8KJJzaciKZ3gfA9hIzvP8nLF.jpg', 'Mike Kersjes is a special-education teacher and football coach in Michigan. Mike doesn’t talk down to his "special" students. He respects them, and he believes they’re capable of achieving great things. When Mike hears about Space Camp, a competitive education program at the U.S. Space and Rocket Center, he gets an idea. Even though the program is designed for gifted science students, Mike decides participating in the summer program would do wonders for the self-esteem of his young students, one in particular who wants to be an astronaut.', NULL, NULL, 1.3602, 6.9, 0, 7.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12328, 46405, 'tt2400391', NULL, 'Legit', 'Legit', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/4wKawZKCcWpQYJXDB5XBSMRCWDm.jpg', 'https://image.tmdb.org/t/p/original/bYNT4gF329uu2RAXvnoT0mBWbeC.jpg', 'Jim Jefferies, an edgy, foul-mouthed stand-up comedian from Australia, in his mid-30s and living in LA, is endeavoring to make his life and career more “legit,” only to find it a difficult, uncomfortable uphill struggle every step of the way. Jim is encouraged in his quest by Steve, his neurotic best friend and roommate, a cyber-law library salesman who struggles to stay on his feet in the wake of a divorce, and Steve’s brother Billy, who suffers from advanced staged Muscular Dystrophy and is confined to a wheelchair.', NULL, NULL, 4.1177, 7.354, 0, 6.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
