INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12344, 1677, 'tt0350258', NULL, 'Ray', 'Ray', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/tSPC7sO2XYNL9QcMmK88tuUALL5.jpg', 'https://image.tmdb.org/t/p/original/umtxTkop7Ec9UFynjB7Z53lmkX1.jpg', 'Born on a sharecropping plantation in Northern Florida, Ray Charles went blind at seven. Inspired by a fiercely independent mom who insisted he make his own way, He found his calling and his gift behind a piano keyboard. Touring across the Southern musical circuit, the soulful singer gained a reputation and then exploded with worldwide fame when he pioneered coupling gospel and country together.', NULL, NULL, 7.458, 7.452, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12345, 59068, 'tt0078344', NULL, 'Sister Emanuelle', 'Suor Emanuelle', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/eRmBJGmljHY9o7OHpcmPfdMKqQg.jpg', 'https://image.tmdb.org/t/p/original/7SyXKnL76PqHtIcGdUWnrOgdEkm.jpg', 'Sister Emanuelle and Sister Nanà go to meet Mr. Cazzabriga, who has a problem: his wild-child daughter, Monica, who he wants to send to a Catholic school to remove her from temptations around the house.', NULL, NULL, 2.5265, 5.4, 0, 9.03, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12346, 1439, 'tt0166485', NULL, 'Anna and the King', 'Anna and the King', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/PIlOkljucv7HnvATbn4JwrAvSn.jpg', 'https://image.tmdb.org/t/p/original/jW1HUCofeIYSpLLbVqVSsm7nMdN.jpg', 'The story of the romance between the King of Siam (now Thailand) and the widowed British school teacher Anna Leonowens during the 1860s. Anna teaches the children and becomes romanced by the King. She convinces him that a man can be loved by just one woman.', NULL, NULL, 6.4184, 6.792, 0, 9.08, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12347, 113610, 'tt0207051', NULL, 'The Journey to Kafiristan', 'Die Reise nach Kafiristan', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/hlj35gh97DPvxgLcSezlZPvwPOO.jpg', NULL, 'In 1939, the author Annemarie Schwarzenbach and the ethnologist Ella Maillart travel together by car to Kabul, but each is in pursuit of her own project. Annemarie Schwarzenbach, who was among Erika and Klaus Mann''s circle of friends in the 30s, is searching for a place of refuge in the Near East to discover her own self. Ella Maillart justifies her restlessness, her need for movement and travel, with a scientific pretext: she would like to explore the mysterious Kafiristan Valley and make a name for herself with publications on the archaic life of the nomads living there. Both women are on the run, but political developments and their own biographies catch up with them again and again. Their mutual journey through the outside world, which runs from Geneva via the Balkans and Turkey to Persia, is compounded by the inner world of emotions with a tender love story.', NULL, NULL, 0.7229, 3.611, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12348, 19666, 'tt0169102', NULL, 'Lagaan: Once Upon a Time in India', 'लगान', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/yNX9lFRAFeNLNRIXdqZK9gYrYKa.jpg', 'https://image.tmdb.org/t/p/original/76VwduxQMkVXOUktps85dE0lLeP.jpg', 'The year is 1893 and India is under British occupation. In a small village, the tyrannical Captain Russell has imposed an unprecedented land tax on its citizens. Outraged, Bhuvan, a rebellious farmer, rallies the villagers to publicly oppose the tax. Russell offers a novel way to settle the dispute: he challenges Bhuvan and his men to a game of cricket, a sport completely foreign to India. If Bhuvan and his men can defeat Russell''s team, the tax will be repealed.', NULL, NULL, 3.1333, 7.273, 0, 9.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12349, 65494, 'tt4786824', NULL, 'The Crown', 'The Crown', 'tv', 2016, 'https://image.tmdb.org/t/p/w500/1M876KPjulVwppEpldhdc8V4o68.jpg', 'https://image.tmdb.org/t/p/original/8VXhcrl5z2I1zEU9X3pkkNrZlD.jpg', 'The gripping, decades-spanning inside story of Her Majesty Queen Elizabeth II and the Prime Ministers who shaped Britain''s post-war destiny. 

The Crown tells the inside story of two of the most famous addresses in the world – Buckingham Palace and 10 Downing Street – and the intrigues, love lives and machinations behind the great events that shaped the second half of the 20th century. Two houses, two courts, one Crown.', NULL, NULL, 52.6864, 8.186, 0, 8.52, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12350, 1092936, 'tt33382323', NULL, 'The Holy Boy', 'La valle dei sorrisi', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/2jpKQ6xhcxaNXOUDeQpyHNUcWr1.jpg', 'https://image.tmdb.org/t/p/original/n7wHpEFThBgm15bUH7e07frPJvV.jpg', 'A PE teacher moves to a isolated mountain village where the people appear to live in unshakeable serenity, but soon stumbles across a disturbing ritual. Once a week, the locals are freed of their pain by a lonely boy born with the power to heal one''s soul just by hugging them. Trying to rescue him from this madness, the man unleashes his dark side.', NULL, NULL, 5.8158, 6.857, 0, 1.02, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12351, 632357, 'tt9419056', NULL, 'The Unholy', 'The Unholy', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/bShgiEQoPnWdw4LBrYT5u18JF34.jpg', 'https://image.tmdb.org/t/p/original/jw6ASGRT2gi8EjCImpGtbiJ9NQ9.jpg', 'Alice is a young hearing-impaired girl who, after a supposed visitation from the Virgin Mary, is inexplicably able to hear, speak and heal the sick. As word spreads and people from near and far flock to witness her miracles, a disgraced journalist hoping to revive his career visits the small New England town to investigate. When terrifying events begin to happen all around, he starts to question if these phenomena are the works of the Virgin Mary or something much more sinister.', NULL, NULL, 6.7899, 6.542, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
