INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12368, 225, 'tt12749392', NULL, 'Sharpe', 'Sharpe', 'tv', 1993, 'https://image.tmdb.org/t/p/w500/adoq3P4qCeDquGXjtcwDDXECESH.jpg', 'https://image.tmdb.org/t/p/original/64TCdZjKoFiJDmGg6S8XBzLgOgt.jpg', 'Sharpe is a British series of television dramas starring Sean Bean as Richard Sharpe, a fictional British soldier in the Napoleonic Wars. Sharpe is the hero of a number of novels by Bernard Cornwell; most, though not all, of the episodes are based on the books. Produced by Celtic Films and Picture Palace Films for the ITV network, the series was shot mainly in Turkey and the Crimea, although some filming was also done in England, Spain and Portugal.

The series originally ran from 1993 to 1997. In 2004, as part of ITV''s new set of drama, ITV announced that it intended to produce new episodes of Sharpe, in co-production with BBC America, loosely based on his time in India, with Sean Bean continuing his role as Sharpe. Sharpe''s Challenge is a two-part adventure; part one premiered on ITV on 23 April 2006, with part two being shown the following night. With more gore than earlier episodes, the show was broadcast by BBC America in September 2006.', NULL, NULL, 11.6118, 8.014, 0, 1.06, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
