INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12382, 32235, 'tt0322659', NULL, 'Northfork', 'Northfork', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/jb3qheP75UgVibpnfubotrBDY5v.jpg', 'https://image.tmdb.org/t/p/original/2u8uQchpm5zUIwax4XdWqZF6DNY.jpg', 'The year is 1955, and a great flood is coming to Northfork, Montana. A new hydroelectric dam is about to be installed in the mountains above the town, ready to submerge the valley in the name of progress. It is the responsibility of a six-man Evacuation Committee to relocate the townsfolk to higher ground. Most have duly departed, but a few stubborn stragglers remain – among them a priest caring for a sickly orphan, a boy whose fevered visions are leading him to believe he is a member of a roaming band of lost angels desperately searching for a way home.', NULL, NULL, 2.3147, 5.988, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12383, 38904, 'tt0119723', NULL, 'Mrs. Dalloway', 'Mrs. Dalloway', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/kJURxFCyfqjTss7vTVMuUobHcye.jpg', 'https://image.tmdb.org/t/p/original/a7dvEl0hRPbGmplEFEJMJwTuGzK.jpg', 'Clarissa Dalloway looks back on her youth as she readies for a gathering at her house. The wife of a legislator and a doyenne of London''s upper-crust party scene, Clarissa finds that the plight of ailing war veteran Septimus Warren Smith reminds her of a past romance with Peter Walsh. In flashbacks, young Clarissa explores her possibilities with Peter.', NULL, NULL, 1.8899, 5.671, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12384, 12863, 'tt0135727', NULL, 'Emily of New Moon', 'Emily of New Moon', 'tv', 1998, 'https://image.tmdb.org/t/p/w500/vFkpGd5Ax5DDBXGmqPsfRNKQg7a.jpg', 'https://image.tmdb.org/t/p/original/hbmGaJayGUlmVhdjZZUvipn8B.jpg', 'Emily of New Moon is a Canadian television series, which aired on CBC Television from 1998 to 2000. The series originally aired in the United States on the Cookie Jar Toons block on This TV and it is currently seen in Canada on the Viva, Bravo! and Vision TV cable channels. The series, produced by Salter Street Films, was based on the Emily of New Moon series of novels by Lucy Maud Montgomery. The series consisted of three seasons of thirteen episodes and one season of seven episodes, for a total of forty-six. The executive producers were Micheline Charest, Michael Donovan, and Ronald Weinberg.

The series starred Martha MacIsaac as the titular orphan Emily Starr. Susan Clark and Sheila McCarthy played Emily''s aunts Elizabeth and Laura, who had taken on the responsibility of raising Emily following her father''s death, and Stephen McHattie played her cousin Jimmy. Susan Clark left the series after the first season when her character, Elizabeth, was killed off.

Recurring cast included Chip Ciupka as Mr. Carpenter, Peter Donaldson as Ian Bowles, Richard Donat as Dr. Burnley, Kris Lemche as Perry Miller, John Neville as Uncle Malcolm, Jessica Pellerin as Ilse Burnley, Shawn Roberts as Teddy Kent, and Linda Thorson as Cousin Isabel.', NULL, NULL, 3.7668, 8.833, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
