INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12461, 22478, 'tt0094663', NULL, 'Another Woman', 'Another Woman', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/ds4CcnlACh0r1r3VGa7y85dz72R.jpg', 'https://image.tmdb.org/t/p/original/2cH8vxci9QjUP9oT2OLW2OHn6U6.jpg', 'Marion is a woman who has learned to shield herself from her emotions. She rents an apartment to work undisturbed on her new book, but by some acoustic anomaly she can hear all that is said in the next apartment in which a psychiatrist holds his office. When she hears a young woman tell that she finds it harder and harder to bear her life, Marion starts to reflect on her own life. After a series of events she comes to understand how her unemotional attitude towards the people around her affected them and herself.', NULL, NULL, 2.421, 6.831, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
