INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12463, 22572, 'tt0093171', NULL, 'Hell Comes to Frogtown', 'Hell Comes to Frogtown', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/7ry5Sh2oFBUj8zqWzAx5Xm8j79i.jpg', 'https://image.tmdb.org/t/p/original/2E3DhgwTK7RnQ9oO2zjiYVpXIn2.jpg', '''Hell'' is the name of the hero of the story. He''s a prisoner of the women who now run the USA after a nuclear/biological war. Results of the war are that mutants have evolved, and the human race is in danger of extinction due to infertility. Hell is given the task of helping in the rescue of a group of fertile women from the harem of the mutant leader (resembling a frog). Hell cannot escape since he has a bomb attached to his private parts which will detonate if he strays more than a few hundred yards from his guard.', NULL, NULL, 2.7607, 5.503, 0, 10.51, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
