INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12466, 780382, 'tt10945288', NULL, 'The Wolf and the Lion', 'Le Loup et le Lion', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/x3JsrunysUwsIV9XS7hQtZG4knm.jpg', 'https://image.tmdb.org/t/p/original/lKvMfb4A7AHy4UzIWzFR8vJbaeb.jpg', 'After her grandfather''s death, 20-year-old Alma decides to go back to her childhood home - a little island in the heart of the majestic Canadian forest. Whilst there, she rescues two helpless cubs: a wolf and a lion. They forge an inseparable bond, but their world soon collapses as the forest ranger discovers the animals and takes them away. The two cub brothers must now embark on a treacherous journey across Canada to be reunited with one another and Alma once more.', NULL, NULL, 4.8596, 7.468, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12467, 118153, 'tt0049358', NULL, 'Ilya Muromets', 'Илья Муромец', 'movie', 1956, 'https://image.tmdb.org/t/p/w500/o56Hm5uR7FkYY4JJz2X8pfXStrm.jpg', 'https://image.tmdb.org/t/p/original/dOqFKzcTRPOuAjBpNevHLODP5Zj.jpg', 'Paralyzed since birth, Ilya can only watch helplessly as his village is plundered by barbarians. But when a mysterious traveler arrives with a magic elixir that restores him to full health, Ilya begins an adventure to protect the village and the royal family from harm.', NULL, NULL, 1.4482, 5.087, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12468, 1114, 'tt0373861', NULL, 'The Story of the Weeping Camel', 'Die Geschichte vom weinenden Kamel', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/c3SAAO5hNJqLWLlJr9TZ6CQ8eGI.jpg', 'https://image.tmdb.org/t/p/original/8jB2BJAbXTVAUl3GvbyGCEXKXMe.jpg', 'When a Mongolian nomadic family''s newest camel colt is rejected by its mother, a musician is needed for a ritual to change her mind.', NULL, NULL, 1.8079, 7.1, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12469, 565911, 'tt39374313', NULL, 'Attila', 'Attila', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/oRoULQnyJldHFdM8aoVhC2AAec7.jpg', 'https://image.tmdb.org/t/p/original/gHqi3bDJtXF1gEneXh5xriNleGH.jpg', 'First staged at the Teatro La Fenice in 1846, Verdi’s ninth opera, Attila, returns to the stage of La Scala on December 7th. Following the inauguration of the 2015-2016 Season with Giovanna d’Arco and in anticipation of Macbeth, with Attila Musical Director Riccardo Chailly continues his study of Verdi’s early works, renewing a successful collaboration with creative director Davide Livermore that began with his acclaimed production of Donizetti’s Don Pasquale for La Scala. In this complex opera Verdi experiments with fresh perspectives, featuring spectacular historical settings, introspective angles and moral uncertainties. Attila demands of its performers not only passion and confidence, but also the ability to find subtle accents and psychological nuances.', NULL, NULL, 0.6824, 0.0, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12470, 644613, 'tt7985648', NULL, 'The Legend of Tomiris', 'Томирис', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/5PJqVblJsq4LfninHPoEzkp1Tuc.jpg', 'https://image.tmdb.org/t/p/original/2S0J4PWNY95uLodCAfY7rhAVKla.jpg', 'This is the story of the life of the great queen of the steppe - legendary Tomiris. She is destined to become a skillful warrior, survive the loss of close people and unite the Scythian/Saka tribes under her authority.', NULL, NULL, 2.3394, 6.859, 0, 10.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
