INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12476, 7171, 'tt1219817', NULL, 'Going Postal', 'Going Postal', 'tv', 2010, 'https://image.tmdb.org/t/p/w500/i03NYQoPmw40fodRPkSFt7nrot9.jpg', 'https://image.tmdb.org/t/p/original/oMgRyddjdo4UzzXmgFZpy9GVs4N.jpg', 'Moist von Lipwig is a con-man with a particular talent-- he is utterly unremarkable. When his execution is stayed in Terry Pratchett''s remarkable Discworld, he must work off his debt to society as the land''s head Postman. Things are not always as they seem, and soon Lipwig is delivering mail for his very life!', NULL, NULL, 6.0183, 7.195, 0, 8.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (12477, 11450, 'tt0110932', NULL, 'Quiz Show', 'Quiz Show', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/yoGJo1h3Hl2exXPVcG9UXWDENtX.jpg', 'https://image.tmdb.org/t/p/original/R5yzaNz6IE2107lcmnzBSerCBP.jpg', 'Herbert Stempel''s transformation into an unexpected television personality unfolds as he secures victory on the cherished American game show, ''Twenty-One.'' However, when the show introduces the highly skilled contestant Charles Van Doren to replace Stempel, it compels Stempel to let out his frustrations and call out the show as rigged. Lawyer Richard Goodwin steps in and attempts to uncover the orchestrated deception behind the scenes.', NULL, NULL, 5.688, 7.25, 0, 1.01, '2026-08-27 07:35:55', '2026-08-27 07:35:55');
