UPDATE "recommendations" SET "tmdb_id"=6795, "imdb_id"='tt0406375', "igdb_id"=NULL, "title"='Zathura: A Space Adventure', "original_title"='Zathura: A Space Adventure', "media_type"='movie', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/gDb5BW2NLqZ9cvg9nyzkZVvmgze.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/s9Bn7Mx4U9cWOR1WdFZjU1DTAkh.jpg', "overview"='After their father is called into work, two young boys, Walter and Danny, are left in the care of their teenage sister, Lisa, and told they must stay inside. Walter and Danny, who anticipate a boring day, are shocked when they begin playing Zathura, a space-themed board game, which they realize has mystical powers when their house is shot into space. With the help of an astronaut, the boys attempt to return home.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.5825, "vote_average"=6.451, "is_ambiguous"=0, "evidence_score"=1.70292307692307716e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=269;
