UPDATE "recommendations" SET "tmdb_id"=378018, "imdb_id"='tt4255304', "igdb_id"=NULL, "title"='The Void', "original_title"='The Void', "media_type"='movie', "release_year"=2016, "poster_url"='https://image.tmdb.org/t/p/w500/2WhZAPi3vomEQdzAPIYTvmvWaxI.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oZwwwezJFlHmQGBRJDLmENXwOIt.jpg', "overview"='In the middle of a routine patrol, officer Daniel Carter happens upon a blood-soaked figure limping down a deserted stretch of road. He rushes the young man to a nearby rural hospital staffed by a skeleton crew, only to discover that patients and personnel are transforming into something inhuman. As the horror intensifies, Carter leads the other survivors on a hellish voyage into the subterranean depths of the hospital in a desperate bid to end the nightmare before it''s too late.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.5232, "vote_average"=6.023, "is_ambiguous"=0, "evidence_score"=6.18437931034482772e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=977;
