UPDATE "recommendations" SET "tmdb_id"=12593, "imdb_id"='tt0068612', "igdb_id"=NULL, "title"='Fritz the Cat', "original_title"='Fritz the Cat', "media_type"='movie', "release_year"=1972, "poster_url"='https://image.tmdb.org/t/p/w500/llgCW1Y99WO7DNiX3ZOncLJBIAm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/udY0Gw8BB99jsJzARsJhctLqUZ6.jpg', "overview"='In late 1960s New York City, fed up with monotonous college life and police repression, free-spirited Fritz, an impenitent seducer and unrestrained party-animal, decides to explore the world. And just like that, as he flees NYC, heading to San Francisco, Fritz embarks on an endless adventure of illumination. Immersed in a world surrounded by drugs and sex, Fritz participates in mad orgies, brings about a revolution, incites mass urban riots, and crosses paths with drug-addled Nazi bikers.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.8606, "vote_average"=6.213, "is_ambiguous"=0, "evidence_score"=1.42370000000000018e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=1235;
UPDATE "recommendations" SET "tmdb_id"=14239, "imdb_id"='tt0104009', "igdb_id"=NULL, "title"='Cool World', "original_title"='Cool World', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/mqzRUHNtFwmgJCmSnvq3JnX0xgZ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uRUAwzXOU75vmO0CD1RzY0CaZ8d.jpg', "overview"='While incarcerated for murder, cartoonist Jack Deebs found escape by creating Cool World, a series featuring a voluptuous femme fatale named Holli Would. But the artist becomes a prisoner of his own fantasies when Holli transports Jack into Cool World with a scheme to seduce him and bring herself to life. Hard-boiled detective Frank Harris – the only other human in Cool World – cautions Jack with the law: Noids (humans) don''t have sex with doodles (cartoons). However, flesh proves weaker than ink as Holli takes human form in Las Vegas, staring in a trans-universal chase that threatens the destruction of both worlds.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.5493, "vote_average"=5.655, "is_ambiguous"=0, "evidence_score"=2.20411111111111104e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=1238;
