UPDATE "recommendations" SET "tmdb_id"=414453, "imdb_id"='tt5990474', "igdb_id"=NULL, "title"='Columbus', "original_title"='Columbus', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/3ZE5Wl3CdfUH4BkWRmyMKPHkWHx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xN88RKXxjPAcQsdBz6XavZ00PFh.jpg', "overview"='When a renowned architecture scholar falls suddenly ill during a speaking tour, his son Jin finds himself stranded in Columbus, Indiana - a small Midwestern city celebrated for its many significant modernist buildings. Jin strikes up a friendship with Casey, a young architecture enthusiast who works at the local library.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5676, "vote_average"=7.081, "is_ambiguous"=0, "evidence_score"=2.63354545454545458e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=1813;
UPDATE "recommendations" SET "tmdb_id"=28276, "imdb_id"='tt0053134', "igdb_id"=NULL, "title"='Good Morning', "original_title"='お早よう', "media_type"='movie', "release_year"=1959, "poster_url"='https://image.tmdb.org/t/p/w500/dXy2LFsE0VlHlHJU3SLBdJgrzEq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qH9wiXnx9mU9kNGCH1exaey9CqU.jpg', "overview"='A lighthearted take on director Yasujiro Ozu’s perennial theme of the challenges of inter­generational relationships, Good Morning tells the story of two young boys who stop speaking in protest after their parents refuse to buy a television set. Ozu weaves a wealth of subtle gags through a family portrait as rich as those of his dramatic films, mocking the foibles of the adult world through the eyes of his child protagonists. Shot in stunning color and set in a suburb of Tokyo where housewives gossip about the neighbors’ new washing machine and unemployed husbands look for work as door-to-door salesmen, this charming comedy refashions Ozu’s own silent classic I Was Born, But . . . to gently satirize consumerism in postwar Japan.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.3049, "vote_average"=7.714, "is_ambiguous"=0, "evidence_score"=10.135, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=1814;
