UPDATE "recommendations" SET "tmdb_id"=36819, "imdb_id"='tt0081633', "igdb_id"=NULL, "title"='Time Bandits', "original_title"='Time Bandits', "media_type"='movie', "release_year"=1981, "poster_url"='https://image.tmdb.org/t/p/w500/4VZtpwdhHQSa4LUkvujyGAHb1hG.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qKERrt3UU1ml8Q9zdsLPpoQ5r3.jpg', "overview"='Young history buff Kevin can scarcely believe it when six dwarfs emerge from his closet one night. Former employees of the Supreme Being, they''ve purloined a map charting all of the holes in the fabric of time and are using it to steal treasures from different historical eras. Taking Kevin with them, they variously drop in on Napoleon, Robin Hood and King Agamemnon before the Supreme Being catches up with them.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.5354, "vote_average"=6.626, "is_ambiguous"=0, "evidence_score"=3.23596296296296301e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=2131;
UPDATE "recommendations" SET "tmdb_id"=204436, "imdb_id"='tt1181840', "igdb_id"=NULL, "title"='Jack and the Cuckoo-Clock Heart', "original_title"='Jack et la mécanique du cœur', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/ZSrU2mvlzM5Jr30XtKCU1fziIj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/rjXK74vrvmFMN0vuFw3TViZ18Ha.jpg', "overview"='Jack is born with his heart frozen solid on the coldest day in history. A wise midwife saves him by replacing it with a cuckoo clock. Now Jack must abide by three rules to keep his mechanical heart safe: never touch the clock''s hands, master his anger, and never fall in love. He tries his best, but when he meets a girl named Acacia he falls in love, threatening the delicate balance of his artificial heart.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.0882, "vote_average"=7.219, "is_ambiguous"=0, "evidence_score"=7.84666666666666579e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=2135;
