UPDATE "recommendations" SET "tmdb_id"=22327, "imdb_id"='tt0403702', "igdb_id"=NULL, "title"='Youth in Revolt', "original_title"='Youth in Revolt', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/3J48x7Utjx0sdYIvjsMWnlEbxpV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gcRl1gl8EOEoniQWgz6LPwwlmrD.jpg', "overview"='As a fan of Albert Camus and Jean-Luc Godard, teenage Nick Twisp is definitely out of his element when his mother and her boyfriend move the family to a trailer park. When a pretty neighbor named Sheeni plays records by French crooners, it''s love at first sight for frustrated and inexperienced Nick. Learning that she is dating someone, Nick launches a hilarious quest to find his way into Sheeni''s heart -- and bed.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.1462, "vote_average"=6.135, "is_ambiguous"=0, "evidence_score"=12.26125, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-08-27 07:35:55' WHERE "id"=4838;
