UPDATE "recommendations" SET "tmdb_id"=37305, "imdb_id"='tt1214085', "igdb_id"=NULL, "title"='Soul Eater', "original_title"='ソウルイーター', "media_type"='tv', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/hAszc4fYfKU4SexxiSIigS3z2WU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/yOkNYWCOWLh3HFtUlo3QT1g5pHG.jpg', "overview"='Set in the Shinigami technical school for weapon meisters, the series revolves around 3 groups of each a weapon meister and a human weapon. Trying to make the latter a "Death Scythe" which is the highest title for a weapon and thus fit for use by the Shinigami, they must collect the souls of 99 evil humans and 1 witch. Maka & Soul Eater, Black Star & Tsubaki, and Death the Kid with Patty and Liz Thompson are the characters Soul Eater revolves around. Besides taking the time to gather souls, these students of Shibusen defend Death City from some of the most powerful of creatures while still attending school and trying to become stronger.', "external_url"=NULL, "platforms"=NULL, "popularity"=20.0458, "vote_average"=7.8, "is_ambiguous"=0, "evidence_score"=6.568, "created_at"='2026-08-11 22:09:33', "updated_at"='2026-08-27 07:35:55' WHERE "id"=9571;
