UPDATE "recommendations" SET "tmdb_id"=31858, "imdb_id"='tt0084287', "igdb_id"=NULL, "title"='Made in Britain', "original_title"='Made in Britain', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/8ygBME2MULEQVxqFZzBfje7Jnhz.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ozqCSHGpJz0cZmNS6yVFX0sWGMw.jpg', "overview"='16-year-old skinhead Trevor has no regard for authority, and would rather spend his time stealing cars than sitting in the detention centre to which he is sent. Social worker Harry Parker tries his best, but Trevor is only interested when there''s something in it for him. The centre authorities try to conform Trevor to the norms of society, but he takes no notice, and would rather speak in a torrent of four-letter words and racial abuse.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.3206, "vote_average"=7.001, "is_ambiguous"=0, "evidence_score"=10.28, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10238;
UPDATE "recommendations" SET "tmdb_id"=2731, "imdb_id"='tt0104507', "igdb_id"=NULL, "title"='Indochine', "original_title"='Indochine', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/sAemRfr6mOSwtQ76e4yUQVImo8B.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/sk5YqvIl4jd7xgw7lcoUMYOLjKt.jpg', "overview"='In colonial Vietnam, dashing French naval captain Jean-Baptiste, wealthy plantation owner Éliane Devries, and her adopted Vietnamese daughter Camillevare form the three points of a cross-cultural romantic triangle. As the struggle against European imperialism sweeps Indochina, Jean-Baptiste and Camille have to choose sides and Éliane faces the emotionally difficult challenge of raising the child of her daughter and ex-lover.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.8138, "vote_average"=7.0, "is_ambiguous"=0, "evidence_score"=8.68333333333333357e+00, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10245;
