UPDATE "recommendations" SET "tmdb_id"=12665, "imdb_id"='tt0114168', "igdb_id"=NULL, "title"='Powder', "original_title"='Powder', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/zwVmkbrRdbNceK4drB0imFszGxl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gAeFtnwgF4asNVbmrudWMHOilWj.jpg', "overview"='Harassed by classmates who won''t accept his shocking appearance, a shy young man known as "Powder" struggles to fit in. But the cruel taunts stop when Powder displays a mysterious power that allows him to do incredible things. This phenomenon changes the lives of all those around him in ways they never could have imagined.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.7767, "vote_average"=7.1, "is_ambiguous"=0, "evidence_score"=6.52, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10482;
