UPDATE "recommendations" SET "tmdb_id"=1419169, "imdb_id"=NULL, "igdb_id"=NULL, "title"='The Alien Hand 3', "original_title"='The Alien Hand 3', "media_type"='movie', "release_year"=NULL, "poster_url"='https://image.tmdb.org/t/p/w500/kDSuWwWLtMoh4xvlFH6sU6uNhR6.jpg', "backdrop_url"=NULL, "overview"='Saket, an ordinary individual, stumbles upon a powerful chain that grants him incredible superpowers. With these newfound abilities, Saket becomes the city''s protector, fighting crime and safeguarding its citizens. However, his life takes an unexpected turn when the chain is stolen by Jay, a ruthless villain who seeks to use its power to destroy the world and elevate himself to god-like status. In a race against time, Saket embarks on a mission to reclaim the chain and stop Jay''s destructive plans. Along the way, he encounters a mysterious and powerful superhero named Alien Hand, whose own motives and powers add complexity to their conflict. The movie centers around the intense face-off between Alien hand and Jay, with the fate of the world hanging in the balance.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.4235, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=6.01, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10508;
UPDATE "recommendations" SET "tmdb_id"=4627, "imdb_id"='tt0772181', "igdb_id"=NULL, "title"='Krabat', "original_title"='Krabat', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/zDg4zqjdtSJOFbcqZMGlCD4Jv2M.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/k5s17QWs7DKFVfeueqvNiQseZIv.jpg', "overview"='A 14-year-old orphan named Krabat flees the horrors of the 30 Years War by becoming an apprentice to an ominous master of a mysterious mill. Krabat is not only taught the craft of milling, but is also instructed in the sinister world of the darker arts. When the life of his friend and protector is threatened, Krabat must struggle to free himself from an evil sorcerer''s control in a gripping fight for freedom, friendship and love.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.3951, "vote_average"=5.838, "is_ambiguous"=0, "evidence_score"=11.01, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10518;
