UPDATE "recommendations" SET "tmdb_id"=35114, "imdb_id"='tt0377770', "igdb_id"=NULL, "title"='Destino', "original_title"='Destino', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/7IyDJdaGlU7olLC08mSwLJTmsC3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hsx40OreCcM84gNmOeVssUvetRg.jpg', "overview"='Short film to a song of love lost and rediscovered, a woman sees and undergoes surreal transformations. Her lover''s face melts off, she dons a dress from the shadow of a bell and becomes a dandelion, ants crawl out of a hand and become Frenchmen riding bicycles. Not to mention the turtles with faces on their backs that collide to form a ballerina, or the bizarre baseball game.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9122, "vote_average"=7.2, "is_ambiguous"=0, "evidence_score"=8.76, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10648;
UPDATE "recommendations" SET "tmdb_id"=129465, "imdb_id"='tt1313120', "igdb_id"=NULL, "title"='Hells', "original_title"='HELLS ANGELS', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/wzakuhm5mMxZXt6oP6CbkJuA7rV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1WCuIbszx4XNvaUrZIoBczC4MPp.jpg', "overview"='Amagane Rinne has a fatal accident while hurrying to her first day of school. She suddenly arrives at an awkward school... in Hell, filled with demons. While she struggles and wishes to go back to the world from whence she came, Rinne befriends her demon schoolmates and develops an uncommon bond.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.3575, "vote_average"=6.865, "is_ambiguous"=0, "evidence_score"=9.65, "created_at"='2026-08-19 01:49:52', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10670;
UPDATE "recommendations" SET "tmdb_id"=276908, "imdb_id"='tt2965412', "igdb_id"=NULL, "title"='Comet', "original_title"='Comet', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/4zOOSa5zyJDvqDDKFwUQVMK6eDe.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/znDbUAz0uPgc329iHBiobnnYA2P.jpg', "overview"='When a chance encounter brings together the cynical Dell and the quick-witted Kimberly, the stage is set for a tempestuous love affair that unfolds like a puzzle. As the film zigzags back and forth in time — from a meteor shower in LA, to an encounter in a Paris hotel room, to a fateful phone call — an unforgettable portrait of a relationship emerges.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.316, "vote_average"=6.626, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-08-20 01:43:50', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10686;
UPDATE "recommendations" SET "tmdb_id"=82690, "imdb_id"='tt1772341', "igdb_id"=NULL, "title"='Wreck-It Ralph', "original_title"='Wreck-It Ralph', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nrEupcBwf4O1zihCM34NoXusZDq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3IFRjBDwtk0DlIsDfJ2zEzLjUBi.jpg', "overview"='Wreck-It Ralph is the 9-foot-tall, 643-pound villain of an arcade video game named Fix-It Felix Jr., in which the game''s titular hero fixes buildings that Ralph destroys. Wanting to prove he can be a good guy and not just a villain, Ralph escapes his game and lands in Hero''s Duty, a first-person shooter where he helps the game''s hero battle against alien invaders. He later enters Sugar Rush, a kart racing game set on tracks made of candies, cookies and other sweets. There, Ralph meets Vanellope von Schweetz who has learned that her game is faced with a dire threat that could affect the entire arcade, and one that Ralph may have inadvertently started.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.5804, "vote_average"=7.361, "is_ambiguous"=0, "evidence_score"=3.04666666666666685e+00, "created_at"='2026-08-20 01:43:50', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10692;
UPDATE "recommendations" SET "tmdb_id"=1132704, "imdb_id"='tt2050645', "igdb_id"=NULL, "title"='The Mirror Mask', "original_title"='The Mirror Mask', "media_type"='movie', "release_year"=NULL, "poster_url"=NULL, "backdrop_url"=NULL, "overview"='The Mirror Mask was created as a commission for the 2005 Contour Biennial of Video Art and was originally exhibited in a multi-channel format with drawings. The feature-length edit was made simultaneously. Working from the Biennial’s theme of feminine power, the video’s exploration uses symbols from both Flemish and Egyptian art reinterpreted through CGI, latex sculptures and low-tech animation programs – the images of the past translated onto a frozen computerized canvas.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.4288, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=6.11833333333333317e+00, "created_at"='2026-08-20 01:43:50', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10795;
