UPDATE "recommendations" SET "tmdb_id"=4267, "imdb_id"='tt0108906', "igdb_id"=NULL, "title"='The Kingdom', "original_title"='Riget', "media_type"='tv', "release_year"=1994, "poster_url"='https://image.tmdb.org/t/p/w500/6Z0Hc9o6HIydmGOHok2e4FoWhXD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/seybe1nVuV1cut9yXgFN8R5MdWz.jpg', "overview"='The Kingdom is the most technologically advanced hospital in Denmark, a gleaming bastion of medical science. A rash of uncanny occurrences, however, begins to weaken the staff''s faith in science – a phantom ambulance pulls in every night, but disappears; voices echo in the elevator shaft; and a pregnant doctor''s fetus seems to be developing much faster than is natural.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.8183, "vote_average"=7.64, "is_ambiguous"=0, "evidence_score"=5.9025, "created_at"='2026-08-20 01:43:50', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10852;
