UPDATE "recommendations" SET "tmdb_id"=11878, "imdb_id"='tt0055630', "igdb_id"=NULL, "title"='Yojimbo', "original_title"='用心棒', "media_type"='movie', "release_year"=1961, "poster_url"='https://image.tmdb.org/t/p/w500/tN7kYPjRhDolpui9sc9Eq9n5b2O.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5BBwSVytssbFuSPZE4DtJVhROjN.jpg', "overview"='A nameless ronin, or samurai with no master, enters a small village in feudal Japan where two rival businessmen are struggling for control of the local gambling trade. Taking the name Sanjuro Kuwabatake, the ronin convinces both silk merchant Tazaemon and sake merchant Tokuemon to hire him as a personal bodyguard, then artfully sets in motion a full-scale gang war between the two ambitious and unscrupulous men.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.6311, "vote_average"=8.08, "is_ambiguous"=0, "evidence_score"=8.37333333333333307e+00, "created_at"='2026-08-21 01:43:43', "updated_at"='2026-08-27 07:35:55' WHERE "id"=10993;
