UPDATE "recommendations" SET "tmdb_id"=11065, "imdb_id"='tt0184791', "igdb_id"=NULL, "title"='O', "original_title"='O', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/6zcnbgNm4Es96sfsgoUavqbAed9.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kPOizQXpSS5uK0M4BcUHzK93nmg.jpg', "overview"='Even though he''s the only black student at the elite Palmetto Grove Academy, star basketball player Odin James has the adoration of all, including the team''s coach and the Dean''s beautiful daughter Desi. Odin''s troubled friend Hugo, the coach''s son, deeply resentful of his father''s preference of Odin on and off the court, plots a diabolical scheme to sow the seed of mistrust between O and Desi, setting in motion a disturbing chain of events which erupts into a firestorm of breathtaking intensity.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.1634, "vote_average"=5.924, "is_ambiguous"=0, "evidence_score"=9.26, "created_at"='2026-08-21 01:43:43', "updated_at"='2026-08-27 07:35:55' WHERE "id"=11071;
